 static final String STATUS="https://status.ebeinc.online/api/public/status", P="online.ebeinc.ebeos.widgetcompanion."; static final ExecutorService NET=Executors.newSingleThreadExecutor();
 static PendingIntent act(Context c,String a,int n){Intent i=new Intent(c,ActionReceiver.class).setAction(P+a);return PendingIntent.getBroadcast(c,n,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);} static void set(RemoteViews v,int id,String s){v.setTextViewText(id,s==null?"":s);} static RemoteViews base(Context c,String title){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_generic);set(v,R.id.title,title);v.setViewVisibility(R.id.buttons,View.VISIBLE);return v;}
 static void push(Context c,Class<?> k,RemoteViews v){AppWidgetManager m=AppWidgetManager.getInstance(c);m.updateAppWidget(new ComponentName(c,k),v);} static String pct(long a,long b){return b<=0?"—":Math.round(100d*a/b)+"%";} static int battery(Context c){BatteryManager b=(BatteryManager)c.getSystemService(Context.BATTERY_SERVICE);return b==null?-1:b.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY);} static long[] storage(){StatFs s=new StatFs(Environment.getDataDirectory().getPath());return new long[]{s.getAvailableBytes(),s.getTotalBytes()};}
 static String network(Context c){ConnectivityManager m=(ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);if(m==null)return"OFFLINE";Network n=m.getActiveNetwork();if(n==null)return"OFFLINE";NetworkCapabilities q=m.getNetworkCapabilities(n);if(q==null)return"CONNECTED";String x=q.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?"WI-FI":q.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)?"CELLULAR":q.hasTransport(NetworkCapabilities.TRANSPORT_VPN)?"VPN":"NETWORK";return q.hasTransport(NetworkCapabilities.TRANSPORT_VPN)?x+" · VPN ACTIVE":x;}
 static boolean powerSave(Context c){PowerManager p=(PowerManager)c.getSystemService(Context.POWER_SERVICE);return p!=null&&p.isPowerSaveMode();} static String now(){return DateFormat.getTimeInstance(DateFormat.SHORT).format(new Date());} static String today(){return new SimpleDateFormat("EEE · MMM d",Locale.getDefault()).format(new Date());}
 static void generic(Context c,Class<?> k,String title,String main,String sub,String foot,String a1,String a2,String x1,String x2){RemoteViews v=base(c,title);set(v,R.id.main,main);set(v,R.id.sub,sub);set(v,R.id.footer,foot);set(v,R.id.action1,a1);set(v,R.id.action2,a2);v.setOnClickPendingIntent(R.id.action1,act(c,x1,k.hashCode()));v.setOnClickPendingIntent(R.id.action2,act(c,x2,k.hashCode()+1));push(c,k,v);}
 static void radio(Context c,Class<?> k,boolean compact){RemoteViews v=base(c,compact?"ALLTHINGS140 · COMPACT":"ALLTHINGS140 RADIO · LIVE SERVER");set(v,R.id.main,"Checking station…");set(v,R.id.sub,"Public status gateway");set(v,R.id.footer,"Refreshing · "+now());set(v,R.id.action1,"OPEN RADIO");set(v,R.id.action2,"REFRESH");v.setOnClickPendingIntent(R.id.action1,act(c,"RADIO",k.hashCode()));v.setOnClickPendingIntent(R.id.action2,act(c,"REFRESH",k.hashCode()+1));push(c,k,v);NET.execute(()->{String main="STATUS UNAVAILABLE",sub="Tap refresh to try again",foot="Last attempt · "+now();try{HttpURLConnection h=(HttpURLConnection)new URL(STATUS).openConnection();h.setConnectTimeout(5000);h.setReadTimeout(6000);h.setRequestProperty("Accept","application/json");int code=h.getResponseCode();InputStream in=code>=200&&code<300?h.getInputStream():h.getErrorStream();String body=read(in);if(code>=200&&code<300){JSONObject o=new JSONObject(body);JSONObject d=obj(o,"data","radio","stream","status");if(d==null)d=o;boolean on=bool(d,"online","stream_online","healthy","ok")||"online".equalsIgnoreCase(str(d,"status","state","stream_status"));String title=str(d,"current_title","title","track","song","now_playing");String artist=str(d,"current_artist","artist");int listeners=num(d,"listeners","listener_count","current_listeners");main=on?"ONLINE · LIVE":"SERVER STATUS · "+(str(d,"status","state").isEmpty()?"CONNECTED":str(d,"status","state").toUpperCase(Locale.US));sub=(artist.isEmpty()?"":artist+" — ")+(title.isEmpty()?"ALLTHINGS140 rotation":title);if(listeners>=0)sub+=" · "+listeners+" listening";foot="Live check · "+now();}else foot="HTTP "+code+" · "+now();}catch(Exception e){foot="Cached/connection issue · "+now();}RemoteViews z=base(c,compact?"ALLTHINGS140 · COMPACT":"ALLTHINGS140 RADIO · LIVE SERVER");set(z,R.id.main,main);set(z,R.id.sub,sub);set(z,R.id.footer,foot);set(z,R.id.action1,"OPEN RADIO");set(z,R.id.action2,"REFRESH");z.setOnClickPendingIntent(R.id.action1,act(c,"RADIO",k.hashCode()));z.setOnClickPendingIntent(R.id.action2,act(c,"REFRESH",k.hashCode()+1));push(c,k,z);});}
 static String read(InputStream in)throws Exception{if(in==null)return"";BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(String s;(s=r.readLine())!=null;)b.append(s);return b.toString();} static JSONObject obj(JSONObject o,String...ks){for(String k:ks){JSONObject x=o.optJSONObject(k);if(x!=null)return x;}return null;} static String str(JSONObject o,String...ks){for(String k:ks){Object v=o.opt(k);if(v!=null&&v!=JSONObject.NULL){if(v instanceof JSONObject){JSONObject j=(JSONObject)v;String s=str(j,"title","name","track");if(!s.isEmpty())return s;}else{String s=String.valueOf(v).trim();if(!s.isEmpty())return s;}}}return"";} static boolean bool(JSONObject o,String...ks){for(String k:ks){Object v=o.opt(k);if(v instanceof Boolean&&((Boolean)v))return true;if(v!=null&&("true".equalsIgnoreCase(String.valueOf(v))||"online".equalsIgnoreCase(String.valueOf(v))||"ok".equalsIgnoreCase(String.valueOf(v))))return true;}return false;} static int num(JSONObject o,String...ks){for(String k:ks)if(o.has(k))return o.optInt(k,-1);return-1;}
 public static void refreshAll(Context c){radio(c,RadioFull.class,false);radio(c,RadioCompact.class,true);int b=battery(c);long[] s=storage();generic(c,SystemMonitor.class,"EBE · SYSTEM MONITOR","BAT "+(b<0?"—":b+"%")+" · "+network(c),"Storage "+Formatter.formatFileSize(c,s[0])+" free",powerSave(c)?"BATTERY SAVER ACTIVE":"SYSTEM NORMAL","SYSTEM","REFRESH","SYSTEM","REFRESH");generic(c,AtAGlance.class,"EBE · AT A GLANCE",now(),today()+" · "+network(c),b<0?"EBE OS":"Battery "+b+"%","EBE OS","REFRESH","EBEOS","REFRESH");generic(c,NetworkVpn.class,"EBE · NETWORK & VPN",network(c),"Tap Internet or Tailscale",now(),"INTERNET","TAILSCALE","INTERNET","TAILSCALE");generic(c,DeviceHealth.class,"EBE · DEVICE HEALTH",b<0?"Battery —":"Battery "+b+"%",powerSave(c)?"Battery saver enabled":"Power profile normal","Storage used "+pct(s[1]-s[0],s[1]),"BATTERY","STORAGE","BATTERY","STORAGE");generic(c,QuickPanels.class,"EBE · QUICK PANELS","SYSTEM CONTROLS","Protected Android panels · safe shortcuts",now(),"INTERNET","DISPLAY","INTERNET","DISPLAY");generic(c,Battery.class,"EBE · BATTERY",b<0?"—":b+"%",powerSave(c)?"Battery Saver ON":"Battery Saver OFF",now(),"BATTERY","REFRESH","BATTERY","REFRESH");generic(c,Storage.class,"EBE · STORAGE",Formatter.formatFileSize(c,s[0])+" FREE",Formatter.formatFileSize(c,s[1])+" total · "+pct(s[1]-s[0],s[1])+" used",now(),"STORAGE","REFRESH","STORAGE","REFRESH");}
 public static void openRadio(Context c){String[] p={"online.ebeinc.allthings140radio","online.allthings140radio.radio"};for(String x:p){Intent i=c.getPackageManager().getLaunchIntentForPackage(x);if(i!=null){i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(i);return;}}Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse("https://allthings140radio.online/"));i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(i);}
 static void settings(Context c,String action){Intent i=null;if("INTERNET".equals(action))i=new Intent(Settings.ACTION_WIRELESS_SETTINGS);else if("DISPLAY".equals(action))i=new Intent(Settings.ACTION_DISPLAY_SETTINGS);else if("BATTERY".equals(action))i=new Intent(Settings.ACTION_BATTERY_SAVER_SETTINGS);else if("STORAGE".equals(action))i=new Intent(Settings.ACTION_INTERNAL_STORAGE_SETTINGS);else if("TAILSCALE".equals(action))i=c.getPackageManager().getLaunchIntentForPackage("com.tailscale.ipn");else if("EBEOS".equals(action))i=c.getPackageManager().getLaunchIntentForPackage("online.ebeinc.ebeos");else if("SYSTEM".equals(action))i=new Intent(Settings.ACTION_SETTINGS);if(i!=null){i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);try{c.startActivity(i);}catch(Exception ignored){}}}
 public static class ActionReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){String a=i==null?"":i.getAction();if(a==null)return;a=a.replace(P,"");if("REFRESH".equals(a))refreshAll(c);else if("RADIO".equals(a))openRadio(c);else settings(c,a);}}
 public static abstract class B extends AppWidgetProvider{abstract void u(Context c);public void onUpdate(Context c,AppWidgetManager m,int[] ids){u(c);}public void onEnabled(Context c){u(c);}}
